<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api,apiMessage} from '@/api/client';
import {usageState,tokenText,usageDates,type UsageReport} from '@/aiUsage';
import AggregateTrend from '@/components/AggregateTrend.vue';
const dates=usageDates(),from=ref(dates.from),to=ref(dates.to),report=ref<UsageReport|null>(null),busy=ref(false),error=ref('');
async function load(page=0){if(busy.value)return;busy.value=true;error.value='';try{const result=(await api.get<UsageReport>('/admin/ai/usage',{params:{from:from.value,to:to.value,page,size:10}})).data;if(!result?.totals||!result.runtime?.circuit||!Array.isArray(result.days)||!Array.isArray(result.recent?.items))throw new Error('服务器尚未提供用量统计，请确认已升级后重试。');report.value=result;}catch(reason){error.value=apiMessage(reason);report.value=null;}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section class="section ai-usage" aria-labelledby="ai-usage-title"><header class="section-title"><div><h2 id="ai-usage-title">AI 用量与运行状态</h2><p>只统计请求元数据，不展示成员对话、草稿或私人计划。</p></div></header>
<form class="usage-filter" @submit.prevent="load()"><label>统计开始日期<input v-model="from" type="date" :max="to" :disabled="busy" required /></label><label>统计结束日期<input v-model="to" type="date" :min="from" :max="dates.to" :disabled="busy" required /></label><button class="btn" :disabled="busy">{{busy?'正在读取…':'刷新用量'}}</button></form>
<p v-if="error" class="error-text usage-notice" role="alert">{{error}}</p>
<template v-if="report"><div class="usage-body"><p>统计范围：{{report.from}} 至 {{report.to}} · 北京时间 · 最多31天</p><dl class="usage-totals"><div><dt>接收请求</dt><dd>{{report.totals.requests}}</dd></div><div><dt>成功回复</dt><dd>{{report.totals.succeeded}}</dd></div><div><dt>失败退回</dt><dd>{{report.totals.failed}}</dd></div><div><dt>结果待核实</dt><dd>{{report.totals.unknown}}</dd></div><div><dt>已知输入 token</dt><dd>{{tokenText(report.totals.inputTokens)}}</dd></div><div><dt>已知输出 token</dt><dd>{{tokenText(report.totals.outputTokens)}}</dd></div></dl>
<p class="usage-runtime" role="status">当前服务{{report.runtime.enabled?'已启用':'未启用'}} · 排队 {{report.runtime.queued}} · 生成中 {{report.runtime.running}} · 并发上限 {{report.runtime.maxConcurrent}} · 等待容量 {{report.runtime.queueCapacity}}<template v-if="report.runtime.circuit.circuitOpen"> · 熔断保护中，约 {{report.runtime.circuit.retryAfterSeconds}} 秒后允许新调用</template></p>
<p class="helper-text">token 已知的请求为 {{report.totals.tokenKnownRequests}} / {{report.totals.requests}}。未知不等于零成本；失败或断连也可能产生上游费用。这不是服务商账单，不设置新的金额上限，不自动退款或重试。统计元数据最多保留90天，新记录删除对话后仍保留到期。</p>
<p v-if="report.attempts">尚保留的上游尝试 {{report.attempts.attempts}}，其中修复 {{report.attempts.repairs}}；用量完整 {{report.attempts.tokenKnownAttempts}}。已知尝试输入／输出 {{report.attempts.inputTokens}} / {{report.attempts.outputTokens}} Token，不与父请求用量再相加。平均排队等待 {{report.attempts.averageQueueWaitMs===null?'未知':(report.attempts.averageQueueWaitMs/1000).toFixed(0)+'秒（秒级精度）'}}，有证据 {{report.attempts.waitKnownJobs}} 项；细分随对话到期删除，最多30天，父账本最长90天。</p>
<AggregateTrend title="每日AI请求" :from="report.from" :to="report.to" :rows="report.days.map(d=>({date:d.date,value:d.totals.requests}))" meaning="按北京时间额度日期统计父请求；UNKNOWN不算成功，未知用量不记零。"/>
<details v-if="report.days.length"><summary>每日汇总</summary><ol class="usage-days"><li v-for="day in report.days" :key="day.date"><strong>{{day.date}}</strong><span>{{day.totals.requests}} 次请求 · 成功 {{day.totals.succeeded}} · 失败 {{day.totals.failed}} · 待核实 {{day.totals.unknown}}</span></li></ol></details>
<details v-if="report.reasons?.length"><summary>失败阶段分类（含已修复尝试）</summary><p class="helper-text">按上游尝试计数，不是失败请求总数；删除或过期的对话不再包含在此细分中，最长保留30天。只显示原因码，不读取成员正文。</p><ul><li v-for="item in report.reasons" :key="item.reason">{{item.reason}}：{{item.attempts}} 次尝试</li></ul></details>
<h3>最近请求</h3><p v-if="!report.recent.items.length" class="empty">所选范围没有请求记录。</p><div v-else class="usage-entries"><article v-for="entry in report.recent.items" :key="entry.requestId"><header><div><strong>{{entry.member}}</strong><small>{{entry.email}}</small></div><strong>{{usageState(entry.state)}}</strong></header><dl><div><dt>请求时间</dt><dd>{{new Date(entry.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</dd></div><div><dt>耗时</dt><dd>{{entry.durationMs===null?'未知':`${(entry.durationMs/1000).toFixed(1)} 秒`}}</dd></div><div><dt>输入 / 输出 token</dt><dd>{{tokenText(entry.inputTokens)}} / {{tokenText(entry.outputTokens)}}</dd></div></dl><p>请求编号：{{entry.requestId}}<template v-if="entry.errorCode"> · 错误分类：{{entry.errorCode}}</template></p><p v-if="entry.state==='UNKNOWN'">结果待核实，额度仍占用；此处不会重复调用或修改结算。</p></article></div>
<nav class="usage-paging" aria-label="AI 请求分页"><span>共 {{report.recent.total}} 项 · 第 {{report.recent.page+1}} 页</span><button class="btn" :disabled="busy||report.recent.page===0" @click="load(report.recent.page-1)">上一页</button><button class="btn" :disabled="busy||(report.recent.page+1)*report.recent.size>=report.recent.total" @click="load(report.recent.page+1)">下一页</button></nav></div></template></section></template>
<style scoped>.ai-usage{margin-top:24px;background:#fff;min-width:0}.ai-usage h2{margin:0}.section-title p{font-size:.85rem;color:var(--muted);margin-bottom:0}.usage-filter{display:flex;gap:16px;align-items:end;padding:20px;border-bottom:1px solid var(--line);flex-wrap:wrap}.usage-filter label{display:grid;gap:8px;font-size:.8rem}.usage-body{padding:20px;min-width:0}.usage-body>p{font-size:.85rem;line-height:1.8}.usage-totals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--line);border-left:1px solid var(--line)}.usage-totals>div{padding:16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.usage-totals dt{font-size:.8rem;color:var(--muted)}.usage-totals dd{font-size:1.7rem;color:#002fa7;margin:8px 0 0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.usage-runtime{padding:16px;background:#f7f7f8}.usage-entries{border-top:1px solid var(--line)}.usage-entries article{padding:20px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.usage-entries header{display:flex;gap:16px;justify-content:space-between}.usage-entries small{display:block;color:var(--muted);margin-top:6px}.usage-entries dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;font-size:.8rem}.usage-entries dd{margin:8px 0 0}.usage-entries p{font-size:.75rem;color:var(--muted)}.usage-paging{display:flex;gap:12px;align-items:center;justify-content:flex-end;flex-wrap:wrap}.usage-paging span{margin-right:auto;font-size:.8rem}.usage-days{list-style:none;padding:0}.usage-days li{display:flex;gap:16px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--line);font-size:.8rem}.usage-notice{padding:16px}.ai-usage .btn{min-height:44px}@media(max-width:700px){.usage-body,.usage-filter{padding:16px}.usage-totals{grid-template-columns:repeat(2,minmax(0,1fr))}.usage-totals>div{padding:12px}.usage-totals dd{font-size:1.4rem}.usage-entries dl{grid-template-columns:1fr}.usage-filter label{flex:1;min-width:0}.usage-filter>.btn{width:100%}.usage-entries header{flex-direction:column}.usage-paging span{width:100%}}</style>
